// ?Customized_Render@RTS3DScene@@UAEXAAVRenderInfoClass@@@Z
// partial score=0.22 date=2026-09-27
// cl: /DNDEBUG /DWIN32 /D_WINDOWS /MD /EHsc /Igame/Libraries/Source/WWVegas/WW3D2 /Igame/Libraries/Source/WWVegas /Iinputs/reference/shims/sweep /Iinputs/reference/CnC_Generals_Zero_Hour/GeneralsMD/Code/GameEngine/Include /Iinputs/reference/CnC_Generals_Zero_Hour/GeneralsMD/Code/GameEngine/Source /Iinputs/reference/CnC_Generals_Zero_Hour/GeneralsMD/Code/Libraries/Include /Iinputs/reference/CnC_Generals_Zero_Hour/GeneralsMD/Code/Libraries/Source /Iinputs/reference/CnC_Generals_Zero_Hour/GeneralsMD/Code/Libraries/Source/Compression /Iinputs/reference/CnC_Generals_Zero_Hour/GeneralsMD/Code/GameEngineDevice/Include /Iinputs/reference/CnC_Generals_Zero_Hour/GeneralsMD/Code/Main /Iinputs/reference/CnC_Generals_Zero_Hour/GeneralsMD/Code/Libraries/Source/WWVegas /Iinputs/reference/CnC_Generals_Zero_Hour/GeneralsMD/Code/Libraries/Source/WWVegas/WWLib /Iinputs/reference/CnC_Generals_Zero_Hour/GeneralsMD/Code/Libraries/Source/WWVegas/WW3D2 /Iinputs/reference/CnC_Generals_Zero_Hour/GeneralsMD/Code/Libraries/Source/WWVegas/WWMath /Igame/Libraries/Source/WWVegas/WWDebug /Iinputs/reference/CnC_Generals_Zero_Hour/GeneralsMD/Code/Libraries/Source/WWVegas/WWSaveLoad
// stlport
// Real C++ reconstruction of BFME RTS3DScene::Customized_Render, retail
// 0x007143B0..0x00714727 (888 bytes, ends at `ret 4`).
//
// The name is proven, not inherited from the lift: the RTS3DScene constructor
// at 0x00712F60 installs primary vtable 0x01120BE0 whose slot 23 is the
// 0x00027D30 ILT into this body, and the already-landed
// ?Render@RTS3DScene@@UAEXAAVRenderInfoClass@@@Z (0x00715B70,
// RTS3DScene_Render_Thunk.cpp) calls slot 23 as Customized_Render between
// updateFixedLightEnvironments and Flush.  The Zero Hour source
// RTS3DScene::Customized_Render (Generals/.../W3DScene.cpp:1032) supplies the
// statement order; every scene member offset here is read out of this body's
// retail bytes, not out of the Zero Hour header, whose layout does not match
// BFME.
//
// The first two -I entries are the game's own reconciled WW3D2 headers, which
// the Zero Hour copies on the remaining paths do not carry: BFME added three
// virtuals to RenderObjClass, and only the reconciled header puts Class_ID at
// vtable +0x0c, Render at +0x30, On_Frame_Update at +0x34, Set_User_Data at
// +0x154, Get_User_Data at +0x158, Is_Really_Visible at +0x17c and the three
// unidentified Bits masks at +0x1bc / +0x1c4 / +0x1cc, all of which are the
// operands this body's retail bytes call.  Measured, not assumed.

#define Matrix4x4 Matrix4

#include "Lib/BaseType.h"
#include "Common/PlayerList.h"
#include "Common/Player.h"
#include "WW3D2/rendobj.h"
#include "WW3D2/robjlist.h"
#include "WW3D2/rinfo.h"
#include "WW3D2/camera.h"
#include "WW3D2/shader.h"

// ---------------------------------------------------------------- scene view
// TU-local ABI view.  The vtable is the one the landed
// RTS3DScene_Render_Thunk.cpp already verifies: Render at +0x58,
// Customized_Render at +0x5c, Visibility_Check at +0x6c.  The Zero Hour header
// declares these three in a different order and at different offsets, so it
// cannot supply this layout.  Only the members this body reads or writes are
// claimed; everything between them is padding.
//
//   +0x18  extra pass polygon mode (Int; SimpleSceneClass member)
//   +0x74  UpdateList  (RefRenderObjListClass; &Head == +0x78)
//   +0xec  RenderList  (RefRenderObjListClass; &Head == +0xf0)
//   +0x128 drawTerrainOnly
//   +0x868 customPassMode
//   +0x86c translucentObjectsCount
//   +0x870 translucentObjectsBuffer
//   +0x874 occludedObjectsCount
class __declspec(novtable) RTS3DScene
{
public:
	virtual void slot00();
	virtual void slot01();
	virtual void slot02();
	virtual void slot03();
	virtual void slot04();
	virtual void slot05();
	virtual void slot06();
	virtual void slot07();
	virtual void slot08();
	virtual void slot09();
	virtual void slot10();
	virtual void slot11();
	virtual void slot12();
	virtual void slot13();
	virtual void slot14();
	virtual void slot15();
	virtual void slot16();
	virtual void slot17();
	virtual void slot18();
	virtual void slot19();
	virtual void slot20();
	virtual void slot21();
	virtual void Render(RenderInfoClass &);
	virtual void Customized_Render(RenderInfoClass &);
	virtual void slot24();
	virtual void slot25();
	virtual void slot26();
	virtual void Visibility_Check(CameraClass *camera);

	char pad000[0x14];
	Int m_extraPassPolygonMode;						// +0x18
	char pad01c[0x74 - 0x1c];
	RefRenderObjListClass UpdateList;				// +0x74
	char pad08c[0xec - 0x8c];
	RefRenderObjListClass RenderList;				// +0xec
	char pad104[0x128 - 0x104];
	Bool m_drawTerrainOnly;							// +0x128
	char pad129[0x868 - 0x129];
	Int m_customPassMode;							// +0x868
	Int m_translucentObjectsCount;					// +0x86c
	RenderObjClass **m_translucentObjectsBuffer;		// +0x870
	Int m_occludedObjectsCount;						// +0x874
};

// The custom-pass words the constructor stores are 0..7.  W3DCustomScene.h
// names only the first two; BFME added the rest and this body compares the
// scene word against 3, 4, 5, 6 and 7.  The unnamed ones keep their retail
// numbers rather than a guessed identity.
enum
{
	SCENE_PASS_DEFAULT = 0,			// W3DCustomScene.h
	SCENE_PASS_ALPHA_MASK = 1		// W3DCustomScene.h
};

// ------------------------------------------------------------- global views
// GlobalData byte at +0xdcc gates the terrain pass, the byte at +0xdbd selects
// which of the three Bits masks decides a non-default pass.  Neither has a
// proven identity, so both are named by their offset.
class GlobalData
{
public:
	char pad000[0xdbd];
	unsigned char m_bfmeByteDBD;			// +0xdbd
	char pad_dbe[0xdcc - 0xdbe];
	unsigned char m_bfmeByteDCC;			// +0xdcc
};
extern GlobalData *TheWritableGlobalData;

// The terrain singleton's +0x18f4 byte suppresses the per-object frame update
// and the terrain pass; the same field is spelled m_bfmeField in
// S3GuardedSetters.cpp.
class TerrainLogic
{
public:
	char pad000[0x18f4];
	Bool m_bfmeField;
};
extern TerrainLogic *TheTerrainLogic;

// The live pin at 0x012F1104 is read through two proven virtuals: +0x28 answers
// whether the extra passes are wanted and +0x3c arms them.
class __declspec(novtable) BfmeGlobCC0
{
public:
	virtual void v00();
	virtual void v04();
	virtual void v08();
	virtual void v0c();
	virtual void v10();
	virtual void v14();
	virtual void v18();
	virtual void v1c();
	virtual void v20();
	virtual void v24();
	virtual bool v28();
	virtual void v2c();
	virtual void v30();
	virtual void v34();
	virtual void v38();
	virtual void v3c();
};
extern BfmeGlobCC0 *g_bfmeGlobCC0;

// 0x01306EEC is TheW3DShadowManager; queueShadows(TRUE) stores into its first
// byte (the same pin is spelled g_bfmeGlobQE in Rva006FEB10SceneRender.cpp).
class BfmeGlobQE
{
public:
	unsigned char ready;
};
extern BfmeGlobQE *g_bfmeGlobQE;

// The BFME primary particle-manager table places queueParticleRender at +0x34
// (the same view as Rva006FEB10SceneRender.cpp).
class __declspec(novtable) ParticleSystemManager
{
public:
	virtual void slot00();
	virtual void slot01();
	virtual void slot02();
	virtual void slot03();
	virtual void slot04();
	virtual void slot05();
	virtual void slot06();
	virtual void slot07();
	virtual void slot08();
	virtual void slot09();
	virtual void slot10();
	virtual void slot11();
	virtual void slot12();
	virtual void slot13();
	virtual void queueParticleRender();
};
extern ParticleSystemManager *TheParticleSystemManager;

// The extra material pass the second terrain pass installs.  The tree already
// spells this global ?Rva012F8048StateInstance@@3PAURva012F8048State@@A at
// 0x012F8048; retail hands its value to RenderInfoClass::Push_Material_Pass.
struct Rva012F8048State
{
	char pad000[1];
};
extern Rva012F8048State *Rva012F8048StateInstance;

// A one-byte state word with no proven identity: it is read beside the +0x1bc
// extra-pass query, so it keeps the address in its name.
extern unsigned char g_bfmeRva00EF9C32;		// retail 0x012F9C32

// HighlightRendering is the 0x0133F42C byte raised around the renderOneObject
// call in the extra-pass path (ScreenHilightFilterPostRender.cpp).
extern bool HighlightRendering;

// The current unit accessor, already pinned at the ILT 0x0000E3D1; retail
// reads a byte at +0x20 of its result.
extern int __cdecl bfmeCurrentCU();

// Existing matched ILT 0x00017238 routes to the BFME render helper at
// 0x00713780 (four stack words, the last one always a flag).  No new canonical
// pin: VC7.1 reserves __thiscall in a free-function-pointer typedef, so the
// call goes through the established pointer-to-member cast idiom.
extern void j_00017238();
struct RTS3DSceneRenderOneObjectThunk { void Call(RenderInfoClass &, RenderObjClass *, Int, Int); };
typedef void (RTS3DSceneRenderOneObjectThunk::*RTS3DSceneRenderOneObjectCall)(RenderInfoClass &, RenderObjClass *, Int, Int);

__forceinline void callRenderOneObject(RTS3DScene *scene, RenderInfoClass &rinfo,
	RenderObjClass *robj, Int localPlayerIndex)
{
	union { void (*asFunction)(); RTS3DSceneRenderOneObjectCall asMember; } fnCast;
	fnCast.asFunction = j_00017238;
	(reinterpret_cast<RTS3DSceneRenderOneObjectThunk *>(scene)->*fnCast.asMember)(rinfo, robj, localPlayerIndex, 0);
}

// ------------------------------------------------------------ drawable info
// The retail bytes read the drawable back-pointer at +0x04 and test a single
// BYTE of the render flags at +0x0c.  The flag values are the upstream
// DrawableInfo.h ones: 0x1e is
// ERF_DELAYED_RENDER|ERF_POTENTIAL_OCCLUDER|ERF_IS_NON_OCCLUDER_OR_OCCLUDEE.
struct RetailDrawableInfo
{
	enum ExtraRenderFlags
	{
		ERF_IS_NORMAL = 0,
		ERF_IS_OCCLUDED = 0x01,
		ERF_POTENTIAL_OCCLUDER = 0x02,
		ERF_POTENTIAL_OCCLUDEE = 0x04,
		ERF_IS_TRANSLUCENT = 0x08,
		ERF_IS_NON_OCCLUDER_OR_OCCLUDEE = 0x10,
		ERF_DELAYED_RENDER = ERF_IS_TRANSLUCENT | ERF_POTENTIAL_OCCLUDEE
	};

	int m_shroudStatusObjectID;
	Drawable *m_drawable;					// +0x04
	void *m_ghostObject;					// +0x08
	unsigned char m_flags;					// +0x0c
};

// ?Customized_Render@RTS3DScene@@UAEXAAVRenderInfoClass@@@Z
void RTS3DScene::Customized_Render(RenderInfoClass &rinfo)
{
	RenderObjClass *terrainObject = NULL, *robj;
	m_translucentObjectsCount = 0;		// start of new frame, no translucent objects
	m_occludedObjectsCount = 0;

	Int localPlayerIndex = ThePlayerList ? ThePlayerList->getLocalPlayer()->getPlayerIndex() : 0;

	// The declaration is split from its assignment on purpose: retail's frame is
	// `sub esp,8` (only terrainObject and localPlayerIndex live in it, ebx holds
	// the flag), and the combined `Int x = ...` spelling grows it to `sub esp,0xc`.
	// The De Morgan form of the test below is likewise load-bearing: it is
	// 9 differing bytes better than `!a && !b`.
	Int suppressTerrainPass;
	if (m_customPassMode == SCENE_PASS_DEFAULT)
		Visibility_Check(&rinfo.Camera);
	suppressTerrainPass = TheTerrainLogic ? TheTerrainLogic->m_bfmeField : 0;

	if (m_customPassMode == SCENE_PASS_DEFAULT)
	{
		// Everything in the update list gets its per-frame processing; the
		// terrain object is remembered because it renders first and alone.
		RefRenderObjListIterator it(&UpdateList);
		for (it.First(); !it.Is_Done(); it.Next())
		{
			robj = it.Peek_Obj();
			if (robj->Class_ID() == RenderObjClass::CLASSID_TILEMAP)
			{
				terrainObject = robj;
				// If we are doing water mirror we draw with backface culling
				// inverted; in that case only update when we aren't drawing
				// water, or particle emitters get two updates per frame.
				if (!(suppressTerrainPass | ShaderClass::Is_Backface_Culling_Inverted()))
					robj->On_Frame_Update();
			}
		}

		// Terrain needs to be rendered first.  Don't check visibility: terrain
		// is always visible.
		if (terrainObject && !TheWritableGlobalData->m_bfmeByteDCC && !suppressTerrainPass)
		{
			robj = terrainObject;
			rinfo.light_environment = NULL;		// terrain is self lit
			rinfo.Camera.Set_User_Data(this);	// pass the scene via user data

			if (m_customPassMode == SCENE_PASS_DEFAULT)
			{
				robj->Render(rinfo);
				if (g_bfmeGlobCC0)
				{
					g_bfmeGlobCC0->v3c();
					if (g_bfmeGlobCC0->v28())
					{
						// the shroud pass: extra passes only
						rinfo.Push_Override_Flags(RenderInfoClass::RINFO_OVERRIDE_ADDITIONAL_PASSES_ONLY);
						rinfo.Push_Material_Pass((MaterialPassClass *)Rva012F8048StateInstance);
						robj->Render(rinfo);
						rinfo.Pop_Material_Pass();
						rinfo.Pop_Override_Flags();
					}
				}
			}
			else
			if (m_customPassMode == 3 || m_customPassMode == 4)
			{
				if (robj->_bfme_ro_flag111() || ((unsigned char *)bfmeCurrentCU())[0x20])
					robj->Render(rinfo);
			}
			else
			if (m_customPassMode == 5 || m_customPassMode == 7 || m_customPassMode == 6)
			{
				// extra pass only: the base terrain pass is suppressed
			}
			else
				robj->Render(rinfo);
		}
	}

	if (m_drawTerrainOnly)
		return;

	if (m_customPassMode != 4)
	{
		// loop through all render objects in the list
		RefRenderObjListIterator it(&RenderList);
		for (it.First(); !it.Is_Done();)
		{
			robj = it.Peek_Obj();
			it.Next();	// advance now, in case this one gets deleted

			if (robj->Class_ID() == RenderObjClass::CLASSID_TILEMAP)
				continue;		// we already rendered terrain

			if (!robj->Is_Really_Visible())
				continue;

			if (m_customPassMode == 3 || m_customPassMode == 5 || m_customPassMode == 6)
			{
				if (TheWritableGlobalData->m_bfmeByteDBD)
				{
					int wants = robj->_bfme_ro_flag109();
					if (m_customPassMode == 6)
					{
						if (wants)
							callRenderOneObject(this, rinfo, robj, localPlayerIndex);
					}
					else
					if (m_customPassMode == 5)
					{
						if (!wants)
							callRenderOneObject(this, rinfo, robj, localPlayerIndex);
					}
					else
						callRenderOneObject(this, rinfo, robj, localPlayerIndex);
				}
				else
				if (robj->_bfme_ro_flag111())
				{
					Bool highlight = robj->_bfme_ro_flag113() != 0;
					HighlightRendering = highlight;
					callRenderOneObject(this, rinfo, robj, localPlayerIndex);
					HighlightRendering = false;
				}
			}
			else
			if (m_customPassMode == 7)
			{
				Bool wants = robj->_bfme_ro_flag109();
				if (g_bfmeRva00EF9C32 || wants)
					callRenderOneObject(this, rinfo, robj, localPlayerIndex);
			}
			else
			if (m_customPassMode == SCENE_PASS_DEFAULT)
			{
				// In this mode we delay almost all objects in order to do
				// correct sorting with the stencil.
				RetailDrawableInfo *drawInfo = (RetailDrawableInfo *)robj->Get_User_Data();
				Drawable *draw = NULL;
				if (drawInfo)
					draw = drawInfo->m_drawable;
				if (!(draw && (drawInfo->m_flags & (RetailDrawableInfo::ERF_DELAYED_RENDER |
					RetailDrawableInfo::ERF_POTENTIAL_OCCLUDER |
					RetailDrawableInfo::ERF_IS_NON_OCCLUDER_OR_OCCLUDEE))))
					callRenderOneObject(this, rinfo, robj, localPlayerIndex);
			}
			else
				robj->Render(rinfo);
		}
	}

	// Tell the shadow manager to render shadows at the end of this frame.  Do
	// not draw shadows when there is no terrain present.
	if (g_bfmeGlobQE && terrainObject && !ShaderClass::Is_Backface_Culling_Inverted() &&
		m_extraPassPolygonMode == 0 && m_customPassMode == SCENE_PASS_DEFAULT)
		g_bfmeGlobQE->ready = 1;

	// only render particles once per frame
	if (terrainObject && TheParticleSystemManager && m_extraPassPolygonMode == 0 &&
		m_customPassMode == SCENE_PASS_DEFAULT)
		TheParticleSystemManager->queueParticleRender();
}
